140	func (s *Source) getRegistryTemplates(ctx context.Context, e env.Env, templateName string) {
141		r := cmdCmd.NewDefaultRegistry(ctx, cmdBackend.DefaultLoginManager, pkgWorkspace.Instance, nil, cmdutil.Diag(), e)
142	
143		matches, err := NewTemplateMatcher(templateName)
144		if err != nil {
145			s.addError(err)
146			return
147		}
148	
149		for template, err := range r.ListTemplates(ctx, registry.ListTemplatesOptions{}) {
150			if err != nil {
151				s.addError(fmt.Errorf("could not get template: %w", err))
152				return
153			}
154	
155			if template.Source == "github" && strings.HasPrefix(template.Name, "pulumi/templates/") {
156				// These template are maintained using https://github.com/pulumi/templates, and are
157				// ingested without going through the Pulumi Cloud.
158				continue
159			}
160	
161			t := registryTemplate{template, r, s}
162			if !matches(t) {
163				continue
164			}
165	
166			s.addTemplate(t)
167		}
168	}
