	m = mockRegistry{getTemplate: func(ctx context.Context, s, p, n string, v *semver.Version) (apitype.TemplateMetadata, error) {
		return apitype.TemplateMetadata{}, ErrNotFound
	}}
	_, err = ResolveTemplateFromName(ctx, m, "src/pub/name", nil)
	assert.True(t, errors.Is(err, ErrNotFound))

