	m = mockRegistry{getTemplate: func(ctx context.Context, s, p, n string, v *semver.Version) (apitype.TemplateMetadata, error) {
		if s == "private" {
			return apitype.TemplateMetadata{}, ErrNotFound
		}
		return apitype.TemplateMetadata{Source: s}, nil
	}}
	tm, err = ResolveTemplateFromName(ctx, m, "pub/name", nil)
	require.NoError(t, err)
	assert.Equal(t, "pulumi", tm.Source)

	// two-part both missing wraps ErrNotFound
	m = mockRegistry{getTemplate: func(ctx context.Context, s, p, n string, v *semver.Version) (apitype.TemplateMetadata, error) {
		return apitype.TemplateMetadata{}, ErrNotFound
	}}
	_, err = ResolveTemplateFromName(ctx, m, "pub/name", nil)
	assert.True(t, errors.Is(err, ErrNotFound))

	// single-part discover + version, not found message
	m = mockRegistry{
		listTemplates: func(ctx context.Context, opts ListTemplatesOptions) iter.Seq2[apitype.TemplateMetadata, error] {
			assert.Equal(t, "aws", opts.Name)
			return func(yield func(apitype.TemplateMetadata, error) bool) {
				yield(apitype.TemplateMetadata{Source: "pulumi", Publisher: "pulumi", Name: "aws"}, nil)
			}
		},
		getTemplate: func(ctx context.Context, s, p, n string, v *semver.Version) (apitype.TemplateMetadata, error) {
			return apitype.TemplateMetadata{}, ErrNotFound
		},
	}
	v := semver.MustParse("99.0.0")
	_, err = ResolveTemplateFromName(ctx, m, "aws", &v)
	require.Error(t, err)
	assert.Contains(t, err.Error(), "version 99.0.0 was not found")

