	}
	tm, err = ResolveTemplateFromName(ctx, m, "aws", nil)
	require.NoError(t, err)
	assert.Equal(t, "aws", tm.Name)

	// four-part invalid identifier
	_, err = ResolveTemplateFromName(ctx, mockRegistry{}, "a/b/c/d", nil)
	require.Error(t, err)
