func TestScratchVersioned(t *testing.T) {
	run := func(t *testing.T, url string, getT func(ctx context.Context, s, p, n string, v *semver.Version) (apitype.TemplateMetadata, error)) (*Source, error) {
		mockRegistry := &backend.MockCloudRegistry{
			Mock: registry.Mock{
				GetTemplateF: getT,
				ListTemplatesF: func(ctx context.Context, opts registry.ListTemplatesOptions) iter.Seq2[apitype.TemplateMetadata, error] {
					return func(yield func(apitype.TemplateMetadata, error) bool) {
						yield(apitype.TemplateMetadata{Name: "name1", Source: "private", Publisher: "pub"}, nil)
					}
				},
			},
		}
		mockBackend := &backend.MockBackend{GetReadOnlyCloudRegistryF: func() registry.Registry { return mockRegistry }}
		testutil.MockBackendInstance(t, mockBackend)
		testutil.MockLoginManager(t, &cmdBackend.MockLoginManager{})
		source := newImpl(context.Background(), url, ScopeAll, workspace.TemplateKindPulumiProject,
			templateRepository(workspace.TemplateRepository{}, workspace.TemplateNotFoundError{}),
			env.NewEnv(env.MapStore{"PULUMI_DISABLE_REGISTRY_RESOLVE": "false", "PULUMI_EXPERIMENTAL": "true"}))
		tpls, err := source.Templates()
		_ = tpls
		return source, err
	}

	// three-part with version success
	t.Run("success", func(t *testing.T) {
		called := false
		src, err := run(t, "src/pub/name1@2.0.0", func(ctx context.Context, s, p, n string, v *semver.Version) (apitype.TemplateMetadata, error) {
			called = true
			assert.Equal(t, "src", s)
			assert.Equal(t, "2.0.0", v.String())
			return apitype.TemplateMetadata{Name: n, Source: s, Publisher: p}, nil
		})
		require.NoError(t, err)
		assert.True(t, called)
		tpls, _ := src.Templates()
		require.Len(t, tpls, 1)
	})

	// not found -> "version '2.0.0' not found"
	t.Run("notfound", func(t *testing.T) {
		_, err := run(t, "src/pub/name1@2.0.0", func(ctx context.Context, s, p, n string, v *semver.Version) (apitype.TemplateMetadata, error) {
			return apitype.TemplateMetadata{}, registry.ErrNotFound
		})
		require.Error(t, err)
		assert.Contains(t, err.Error(), "version '2.0.0' not found")
	})

	// VCS-backed -> error
	t.Run("vcs", func(t *testing.T) {
		_, err := run(t, "github/pub/name1@2.0.0", func(ctx context.Context, s, p, n string, v *semver.Version) (apitype.TemplateMetadata, error) {
			return apitype.TemplateMetadata{Name: n, Source: "github", Publisher: p, RepoSlug: ref("gh/repo")}, nil
		})
		require.Error(t, err)
		assert.Contains(t, err.Error(), "VCS-backed")
		assert.Contains(t, err.Error(), "does not support specific versions")
	})

	// name-only with version routes through GetTemplate after discovery
	t.Run("nameonly", func(t *testing.T) {
		called := false
		_, err := run(t, "name1@2.0.0", func(ctx context.Context, s, p, n string, v *semver.Version) (apitype.TemplateMetadata, error) {
			called = true
			assert.Equal(t, "private", s)
			assert.Equal(t, "pub", p)
			return apitype.TemplateMetadata{Name: n, Source: s, Publisher: p}, nil
		})
		require.NoError(t, err)
		assert.True(t, called)
	})
}
